translations.unshift(...[["Disponibilità per completare l’acquisto", "Funds needed to complete the purchase", "Fonds nécessaires pour finaliser l’achat", "Fondos para completar la compra"], ["Quota del prezzo non coperta dal mutuo:", "Purchase price not covered by the mortgage:", "Part du prix non couverte par le prêt :", "Parte del precio no cubierta por la hipoteca:"], ["Risparmi dichiarati:", "Declared savings:", "Épargne déclarée :", "Ahorros declarados:"], ["Mancano", "Missing", "Il manque", "Faltan"], ["per saldare il prezzo, oltre ai fondi necessari per le spese.", "to pay the purchase price, plus the funds needed for costs.", "pour régler le prix, en plus des fonds nécessaires pour les frais.", "para pagar el precio, además de los fondos necesarios para los gastos."], ["Disponibilità residua per le spese:", "Funds remaining for costs:", "Fonds restants pour les frais :", "Fondos restantes para gastos:"], ["Imposte, notaio e altri costi devono essere quantificati e verificati con il consulente.", "Taxes, notary fees and other costs must be quantified and checked with your adviser.", "Les taxes, frais de notaire et autres coûts doivent être chiffrés et vérifiés avec le conseiller.", "Los impuestos, notaría y otros costes deben cuantificarse y comprobarse con el asesor."], ["Disponibilità economica insufficiente per saldare l’acquisto: mancano", "Insufficient funds to complete the purchase: missing", "Fonds insuffisants pour finaliser l’achat : il manque", "Fondos insuficientes para completar la compra: faltan"], ["euro rispetto al prezzo non coperto dal mutuo. Servono inoltre fondi per imposte, notaio e altre spese dell’operazione, non incluse in questo importo.", "euros toward the price not covered by the mortgage. Additional funds are needed for taxes, notary fees and other transaction costs, excluded from this amount.", "euros sur le prix non couvert par le prêt. Des fonds supplémentaires sont nécessaires pour les taxes, frais de notaire et autres frais, exclus de ce montant.", "euros del precio no cubierto por la hipoteca. Se necesitan fondos adicionales para impuestos, notaría y otros gastos, excluidos de este importe."], ["I risparmi coprono soltanto la quota del prezzo non finanziata dal mutuo: non rimane disponibilità per imposte, notaio e altre spese dell’operazione. Occorrono ulteriori fondi da quantificare con il consulente.", "Savings only cover the price not financed by the mortgage: nothing remains for taxes, notary fees and other transaction costs. Additional funds must be quantified with your adviser.", "L’épargne couvre uniquement le prix non financé : aucun fonds ne reste pour les taxes, frais de notaire et autres frais. Les fonds supplémentaires doivent être chiffrés avec le conseiller.", "Los ahorros solo cubren el precio no financiado: no quedan fondos para impuestos, notaría y otros gastos. Deben cuantificarse fondos adicionales con el asesor."]]);
window.previewLocale='it';try{window.previewLocale=localStorage.getItem('primoscore_language')||'it'}catch(e){}
if(!['it','en','fr','es'].includes(window.previewLocale)) window.previewLocale='it';
const languageIndex={it:0,en:1,fr:2,es:3};
const ordered=translations.slice().sort((a,b)=>b[0].length-a[0].length);
const originalText=new WeakMap(),originalAttributes=new WeakMap();
const originalTitle=document.title;
function translateText(value){
 if(window.previewLocale==='it')return value;
 const index=languageIndex[window.previewLocale],trim=value.trim(),exact=translations.find(row=>row[0]===trim);
 if(exact)return value.replace(trim,exact[index]);
 let output=value;
 // Longest phrase first; one replacement pass keeps translated text intact.
 const escaped=ordered.map(row=>row[0].replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));
 const pattern=new RegExp('(?<![\\p{L}])(?:'+escaped.join('|')+')(?![\\p{L}])','gu');
 return output.replace(pattern,match=>translations.find(row=>row[0]===match)[index]);
}
const observer=new MutationObserver(()=>applyLanguage());
function applyLanguage(){
 observer.disconnect();
 document.documentElement.lang=window.previewLocale;
 document.title=translateText(originalTitle);
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 let node;
 while(node=walker.nextNode()){
  if(node.parentElement.closest('script,style,.languages,[data-no-translate]'))continue;
  const cached=originalText.get(node);
  const source=cached&&node.nodeValue===cached.last?cached.source:node.nodeValue;
  const output=translateText(source);
  originalText.set(node,{source,last:output});
  if(node.nodeValue!==output)node.nodeValue=output;
 }
 document.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{
  if(el.closest('.languages'))return;
  let cache=originalAttributes.get(el)||{};
  for(const key of ['placeholder','aria-label'])if(el.hasAttribute(key)){
   const value=el.getAttribute(key),old=cache[key],source=old&&value===old.last?old.source:value,output=translateText(source);
   cache[key]={source,last:output};el.setAttribute(key,output);
  }
  originalAttributes.set(el,cache);
 });
 document.querySelectorAll('[data-lang]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lang===window.previewLocale)));
 document.querySelector('.languages')?.setAttribute('aria-label',({it:'Lingua',en:'Language',fr:'Langue',es:'Idioma'})[window.previewLocale]);
 observer.observe(document.body,{childList:true,subtree:true,characterData:true});
}
document.querySelectorAll('[data-lang]').forEach(button=>button.onclick=()=>{
 window.previewLocale=button.dataset.lang;
 try{localStorage.setItem('primoscore_language',window.previewLocale)}catch(e){}
 const url=new URL(location);url.searchParams.set('lang',window.previewLocale);history.replaceState(null,'',url);
 applyLanguage();
 window.dispatchEvent(new Event('primoscore-language-change'));
});
const queryLanguage=new URLSearchParams(location.search).get('lang');
if(languageIndex[queryLanguage]!==undefined)window.previewLocale=queryLanguage;
applyLanguage();
